import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"44、【姤】 巽下乾上","description":"周易口訣義 - 44、【姤】 巽下乾上","frontmatter":{"title":"44、【姤】 巽下乾上","description":"周易口訣義 - 44、【姤】 巽下乾上"},"headers":[],"relativePath":"classics/koujueyi/046.md","filePath":"classics/koujueyi/046.md"}'),r={name:"classics/koujueyi/046.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_44、【姤】-巽下乾上" tabindex="-1">44、【姤】 巽下乾上 <a class="header-anchor" href="#_44、【姤】-巽下乾上" aria-label="Permalink to “44、【姤】 巽下乾上”">​</a></h1><p>彖曰：姤，遇也。柔遇剛也。「勿用取女」，不可與長也。天地相遇，品物鹹章也。剛遇中正，天下大行也。姤之時義大矣哉！</p><p>象曰：天下有風，姤。後以施命誥四方。</p><p>初六：繫於金柅，貞吉。有攸往，見兇。羸豕孚蹢躅。</p><p>象曰：「繫於金柅」，柔道牽也。</p><p>九二：包有魚，無咎。不利賓。</p><p>象曰：「包有魚」，義不及賓也。</p><p>九三：臀無膚，其行次且，厲，無大咎。</p><p>象曰：「其行次且」，行未牽也。</p><p>九四：包無魚，起兇。</p><p>象曰：「無魚」之「兇」，遠民也。</p><p>九五：以杞包瓜，含章，有隕自天。</p><p>象曰：九五「含章」，中正也。「有隕自天」，志不捨命也。</p><p>上九：姤其角，吝，無咎。</p><p>象曰：「姤其角」，上窮吝也。</p><p>解讀</p><p>「姤，女壯，勿用取女」者，姤者，遇也。初六一柔而遇五剛，譬之人事，即是一女而遇五男。夫女之為道，固合婉娩貞順，處於幽室，待禮乃行。今遇五男，淫壯若斯，故不可取，故曰「女壯，勿用取女」也。象曰：「天下有風，姤」者，風行天下，無物不遇，故是姤象也。「後以施命誥四方」者，後，君也；誥，誡也。風譬王者風教也，故風行草偃，所以人君象此，以施命誥戒於四方也。</p><p>初六，繫於金柅，貞吉。有攸往，見兇。「羸豕孚蹢躅」者，金者，堅剛之物；柅者，制動之主，謂九四也。初六應在九四，若繫於正應，制動由四，即合理之宜，正之吉矣，故曰「繫於金柅，貞吉」也。然初六處遇之初，性又躁動，即是不牽繫於四，而有所往，斯乃兇危立見，故曰「有攸往，見兇」。然淫躁若斯，又如羸弱之豕，蹢躅而進，故曰「羸豕乎蹢躅」也。羸豕，牝豕，為淫醜也。蹢躅，行不正貌。</p><p>「九二，包有魚，無咎，不利賓」者，初六陰柔處下位，故稱「魚」也。初六與二相近，不能逆於所近，樂充九二之包廚，故曰「包有魚」也。初自願來，非己侵奪，故「無咎」也。擅人之物，以為己惠，故「不利賓」也。</p><p>「九三，臀無膚，其行次且，厲，無大咎」者，九三居下卦之上，是一卦之主，今初六與二相得，而九三失其所據，居即不安，行亦不進，故曰「臀無膚，其行次且」。然九三履得其位，非為妄處，直以不遇其時，故致危厲，災非己招，故無大咎，故「厲無咎」也。</p><p>「九四，包無魚，起兇」，初六與二相近，樂充九二之包廚，四失本應，故曰「包無魚」。九四既失其應，即是下無民人，若無人而動，失應而作，有所興為，即致兇災，故曰「起兇」也。</p><p>「九五，以杞包瓜，含章，有隕自天」者，杞，枸杞也；瓜，瓠瓜也。杞生於肥地，瓠瓜為物，繫而不食也。五居尊位，下無其應，猶如杞包瓜，繫而不食，其猶人君雖居貴位，下既無人，何以施其教命？故曰「以杞包瓜」也。下無應援，教命不可行，雖有章美之德，而但包含之，故曰「含章」也。然以剛居尊，懷剛中之德，雖即教命不行，無人敢有傾隕矣。所有隕絕，惟天而已，故曰「有隕自天」也。</p><p>「上九：姤其角，吝，無咎」者，處遇之極，無所復遇，其猶一體之中遇角而已，故曰「姤其角」也。角既處上，即非所安，與不遇無異，故生悔吝。然下既無應，不與物競，故無兇災，故曰「吝無咎」也。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
